class BankAccount {
    private int balance = 1000;

    public synchronized void withdraw(int amount) {
        balance -= amount;
        System.out.println("출금 완료! 잔액: " + balance);
    }
}

public class Main {
    public static void main(String[] args) {
        BankAccount account = new BankAccount();
        // 두 일꾼이 동시에 돈을 뽑으려 한다고 가정합시다.
    }
}
